  1→<?php
  2→
  3→namespace App\Http\Controllers;
  4→
  5→use App\Http\Requests\StoreBirthRegistrationRequest;
  6→use App\Models\Animal;
  7→use App\Models\BirthRegistration;
  8→use App\Models\SubExploitation;
  9→use Illuminate\Http\RedirectResponse;
 10→use Illuminate\Http\Request;
 11→use Illuminate\Support\Facades\DB;
 12→use Inertia\Inertia;
 13→use Inertia\Response;
 14→
 15→class BirthRegistrationController extends Controller
 16→{
 17→    public function create(Request $request): Response
 18→    {
 19→        $exploitation = $request->user()
 20→            ->exploitations()
 21→            ->with(['subExploitations.animals'])
 22→            ->firstOrFail();
 23→
 24→        return Inertia::render('nacimientos/crear', [
 25→            'exploitation' => $exploitation,
 26→            'success' => $request->session()->get('success'),
 27→        ]);
 28→    }
 29→
 30→    public function store(StoreBirthRegistrationRequest $request): RedirectResponse
 31→    {
 32→        $validated = $request->validated();
 33→
 34→        $subExploitation = SubExploitation::findOrFail($validated['sub_exploitation_id']);
 35→        $mother = Animal::findOrFail($validated['mother_id']);
 36→
 37→        return DB::transaction(function () use ($validated, $subExploitation, $mother): RedirectResponse {
 38→            $referenceCode = $this->generateReferenceCode();
 39→
 40→            $birthRegistration = BirthRegistration::create([
 41→                'sub_exploitation_id' => $validated['sub_exploitation_id'],
 42→                'mother_id' => $validated['mother_id'],
 43→                'father_id' => $validated['father_id'] ?? null,
 44→                'birth_type' => $validated['birth_type'],
 45→                'calf_count' => count($validated['calves']),
 46→                'status' => 'submitted',
 47→                'submitted_at' => now(),
 48→                'reference_code' => $referenceCode,
 49→            ]);
 50→
 51→            $createdCalves = [];
 52→
 53→            foreach ($validated['calves'] as $calfData) {
 54→                $assignedCrotal = $this->generateCrotalCode();
 55→
 56→                $calf = $birthRegistration->calves()->create([
 57→                    'sex' => $calfData['sex'],
 58→                    'breed' => $calfData['breed'],
 59→                    'name' => $calfData['name'] ?? null,
 60→                    'birth_date' => $calfData['birth_date'],
 61→                    'assigned_crotal' => $assignedCrotal,
 62→                ]);
 63→
 64→                Animal::create([
 65→                    'sub_exploitation_id' => $subExploitation->id,
 66→                    'crotal_code' => $assignedCrotal,
 67→                    'species' => $subExploitation->species,
 68→                    'breed' => $calfData['breed'],
 69→                    'sex' => $calfData['sex'],
 70→                    'name' => $calfData['name'] ?? null,
 71→                    'birth_date' => $calfData['birth_date'],
 72→                    'mother_id' => $mother->id,
 73→                    'father_id' => $validated['father_id'] ?? null,
 74→                    'status' => 'active',
 75→                ]);
 76→
 77→                $createdCalves[] = [
 78→                    'name' => $calfData['name'] ?? null,
 79→                    'sex' => $calfData['sex'],
 80→                    'crotal' => $assignedCrotal,
 81→                ];
 82→            }
 83→
 84→            $subExploitation->increment('current_capacity', count($validated['calves']));
 85→
 86→            return redirect()->route('nacimientos.create')->with('success', [
 87→                'message' => 'Nacimiento registrado correctamente.',
 88→                'reference_code' => $referenceCode,
 89→                'calves' => $createdCalves,
 90→                'new_capacity' => $subExploitation->fresh()->current_capacity,
 91→            ]);
 92→        });
 93→    }
 94→
 95→    /**
 96→     * Generate a mock reference code in format NC-2026-048-XXXXX.
 97→     */
 98→    private function generateReferenceCode(): string
 99→    {
100→        $year = now()->year;
101→        $sequence = str_pad((string) random_int(1, 99999), 5, '0', STR_PAD_LEFT);
102→
103→        return "NC-{$year}-048-{$sequence}";
104→    }
105→
106→    /**
107→     * Generate a mock crotal code in format ES + 13 digits.
108→     */
109→    private function generateCrotalCode(): string
110→    {
111→        $digits = str_pad((string) random_int(0, 9999999999999), 13, '0', STR_PAD_LEFT);
112→
113→        return "ES{$digits}";
114→    }
115→}
